export function createSiteSupervisorWorkspace({api,state,can,L,e,icon,formatDate,formatDateTime,relativeTime,pageHeader,emptyState,render,toast,formError,navigateToEntity,replaceRoute,openDialog,openDrawer,closeOverlay,openNewDrawing,openTakeoff,openQuickUpload,openNewTask,getProfile}){
  const siteKey='optimum.field.site.v1';
  const dateKey='optimum.field.date.v1';
  const local={snapshot:null,execution:null,weekly:null,eod:null,loading:false,refreshing:false,executionLoading:false,loadedKey:'',siteId:localStorage.getItem(siteKey)||'',workDate:localStorage.getItem(dateKey)||new Date().toISOString().slice(0,10),view:'today',busyAction:'',offlineDraft:null};
  const arr=(v)=>Array.isArray(v)?v:[];
  const num=(v)=>Number(v||0);
  const today=()=>new Date().toISOString().slice(0,10);
  const statusLabel=(v)=>({active:L('نشط','Active'),draft:L('مسودة','Draft'),in_review:L('قيد المراجعة','In review'),submitted:L('مرسل للمراجعة','Submitted'),issued:L('صادر','Issued'),approved:L('معتمد','Approved'),returned:L('مرجع للتعديل','Returned'),blocked:L('متوقفة','Blocked'),in_progress:L('قيد التنفيذ','In progress'),todo:L('مطلوبة','To do'),passed:L('ناجح','Passed'),failed:L('لم يجتز','Failed'),needs_review:L('يحتاج مراجعة','Needs review'),closed:L('مغلق','Closed'),open:L('مفتوحة','Open'),ready_for_review:L('جاهزة للمراجعة','Ready for review'),mitigating:L('جارٍ المعالجة','Mitigating'),resolved:L('تم الحل','Resolved')})[String(v||'').toLowerCase()]||String(v||'').replaceAll('_',' ');
  const priorityLabel=(v)=>({urgent:L('عاجلة','Urgent'),high:L('مهمة','High'),medium:L('عادية','Normal'),low:L('منخفضة','Low')})[v]||v||'';
  const severityLabel=(v)=>({low:L('منخفضة','Low'),medium:L('متوسطة','Medium'),high:L('عالية','High'),critical:L('حرجة','Critical')})[v]||v||'';
  const constraintLabel=(v)=>({material:L('مواد','Material'),permit:L('تصريح','Permit'),client:L('العميل','Client'),design:L('تصميم','Design'),access:L('وصول','Access'),weather:L('طقس','Weather'),technical:L('فني','Technical'),resource:L('موارد','Resources'),other:L('أخرى','Other')})[v]||v||'';
  const profileName=(id)=>getProfile?.(id)?.full_name||L('عضو الفريق','Team member');
  const site=()=>local.snapshot?.site||null;
  const project=()=>local.snapshot?.project||null;
  const caps=()=>local.snapshot?.capabilities||{};
  const cabinets=()=>arr(local.snapshot?.cabinets);
  const drawings=()=>arr(local.snapshot?.drawings);
  const tasks=()=>arr(local.snapshot?.tasks);
  const docs=()=>arr(local.snapshot?.documents);
  const exec=()=>local.execution||{};
  const execCaps=()=>exec().capabilities||{};
  const progress=()=>exec().progress||{};
  const dailyLog=()=>exec().daily_log||null;
  const inspections=()=>arr(exec().inspections);
  const issues=()=>arr(exec().issues);
  const constraints=()=>arr(exec().constraints);
  const readiness=(c)=>c.requirement_count?Math.round((num(c.requirement_ready)/Math.max(1,num(c.requirement_count)))*100):null;
  const selectedSiteLabel=()=>{const s=site(),p=project();return s&&p?`${p.code||''} · ${s.code||''} — ${s.name}`:L('اختر الموقع','Choose site');};
  const executionKey=()=>`${state.companyId}:${local.siteId||'auto'}:${local.workDate}`;
  const offlineDraftKey=()=>`optimum.field.dailyDraft.${state.companyId||'x'}.${local.siteId||'x'}.${local.workDate}`;

  function setBusy(action=''){local.busyAction=action;render();}
  function reset(){local.snapshot=null;local.execution=null;local.weekly=null;local.eod=null;local.loadedKey='';local.siteId=localStorage.getItem(siteKey)||'';local.workDate=localStorage.getItem(dateKey)||today();}

  async function load({force=false}={}){
    if(!state.companyId)return;
    const key=`${state.companyId}:${api.user?.id||''}:${local.siteId||'auto'}`;
    if(local.loading||(!force&&local.loadedKey===key&&local.execution))return;
    local.loading=true;render();
    try{
      const snap=await api.rpc('site_supervisor_workspace',{p_company_id:state.companyId,p_site_id:local.siteId||null,p_limit:28});
      local.snapshot=snap||{};
      if(snap?.site?.id){local.siteId=snap.site.id;localStorage.setItem(siteKey,local.siteId);}
      local.loadedKey=`${state.companyId}:${api.user?.id||''}:${local.siteId||'auto'}`;
      await loadExecution({force:true,silent:true});
    }catch(err){formError(err,L('تعذر تحميل مساحة مشرف الموقع','Could not load Site Supervisor Workspace'));}
    finally{local.loading=false;local.refreshing=false;render();}
  }

  async function loadExecution({force=false,silent=false}={}){
    if(!state.companyId||!local.siteId)return;
    if(local.executionLoading&&!force)return;
    local.executionLoading=true;if(!silent)render();
    try{
      const [execution,eod]=await Promise.all([
        api.rpc('site_execution_workspace',{p_company_id:state.companyId,p_site_id:local.siteId,p_work_date:local.workDate,p_limit:50}),
        api.rpc('site_end_of_day_review',{p_company_id:state.companyId,p_site_id:local.siteId,p_work_date:local.workDate})
      ]);
      local.execution=execution||{};local.eod=eod||null;
      try{local.offlineDraft=JSON.parse(localStorage.getItem(offlineDraftKey())||'null');}catch{local.offlineDraft=null;}
    }catch(err){if(!silent)formError(err,L('تعذر تحميل تنفيذ الموقع','Could not load site execution'));}
    finally{local.executionLoading=false;if(!silent)render();}
  }

  async function reloadAll(){local.refreshing=true;local.loadedKey='';await load({force:true});}

  function metric(ic,value,label,tone=''){
    return `<article class="field-metric ${tone}"><span>${icon(ic,18)}</span><div><strong>${value}</strong><small>${e(label)}</small></div></article>`;
  }

  function nextAction(){
    const p=progress();
    if(num(p.critical_issues)>0)return {icon:'alert',tone:'danger',title:L('عالج المشكلة الحرجة أولًا','Handle the critical issue first'),copy:L('هناك مشكلة حرجة مفتوحة في الموقع وتحتاج قرارًا قبل إكمال اليوم.','A critical field issue is open and needs attention before closing the day.'),action:'data-action="field-view-issues"'};
    if(num(p.inspections_failed)>0)return {icon:'shield',tone:'warning',title:L('راجع الفحص الذي لم يجتز','Review the failed inspection'),copy:L('الفحص الفاشل يحتاج معالجة أو مهمة تصحيحية واضحة.','A failed inspection needs a clear corrective action or task.'),action:'data-action="field-view-inspections"'};
    const overdue=tasks().find(t=>t.due_at&&new Date(t.due_at)<new Date());
    if(overdue)return {icon:'alert',tone:'danger',title:L('ابدأ بالمهمة المتأخرة','Start with the overdue task'),copy:overdue.title,action:`data-action="field-open-entity" data-type="task" data-id="${e(overdue.id)}"`};
    const draft=drawings().find(d=>d.revision_status==='draft'||d.status==='draft');
    if(draft)return {icon:'drafting',tone:'primary',title:L('أكمل الرسم الجاري','Continue the active drawing'),copy:`${draft.drawing_no} · ${draft.title}`,action:`data-action="field-open-drawing" data-id="${e(draft.id)}"`};
    const missing=cabinets().find(c=>num(c.requirement_count)>num(c.requirement_ready));
    if(missing)return {icon:'box',tone:'warning',title:L('أكمل أدلة الكابينة','Complete cabinet evidence'),copy:`${missing.code} — ${missing.name}`,action:`data-action="field-open-cabinet" data-id="${e(missing.id)}"`};
    return {icon:'check',tone:'success',title:L('راجع يومك قبل الإغلاق','Review your day before closeout'),copy:L('راجع الأعمال والفحوصات والأدلة ثم أرسل التقرير عندما يصبح جاهزًا.','Review work, inspections, and evidence, then submit the report when ready.'),action:'data-action="field-end-day"'};
  }

  function quickActions(){
    const c=caps(),x=[];
    if(c.can_create_drawing)x.push(['field-new-drawing','drafting',L('رسم جديد','New drawing'),L('المشروع والموقع جاهزان تلقائيًا','Project & site are prefilled')]);
    if(c.can_edit_drawing&&drawings().length)x.push(['field-open-latest-drawing','edit',L('استكمال الرسم','Continue drawing'),L('ارجع لآخر رسم مباشرة','Resume the latest drawing')]);
    if(c.can_edit_takeoff&&drawings().length)x.push(['field-open-latest-takeoff','fileSpreadsheet',L('الحصر','Takeoff'),L('حصر آخر رسم بدون بحث','Latest drawing takeoff')]);
    if(c.can_upload)x.push(['field-upload','camera',L('صورة أو دليل','Photo / evidence'),L('يرث سياق الموقع ويتحفظ في CDE','Site context + CDE storage')]);
    if(execCaps().can_edit)x.push(['field-new-inspection','shield',L('ابدأ فحص','Start inspection'),L('Checklist واضحة مع نتيجة لكل بند','Guided field checklist')]);
    if(execCaps().can_edit)x.push(['field-new-issue','alert',L('بلغ عن مشكلة','Report issue'),L('مشكلة مرتبطة بالموقع والكابينة','Site/cabinet-linked snag')]);
    if(execCaps().can_edit)x.push(['field-new-constraint','pause',L('سجل عائق','Log constraint'),L('سجل سبب التعطيل وتأثيره','Record blocker and impact')]);
    if(c.can_create_task)x.push(['field-new-task','checkSquare',L('مهمة أو ملاحظة','Task / note'),L('تتربط بالموقع تلقائيًا','Automatically site-linked')]);
    return `<div class="field-action-grid field-action-grid-v10">${x.map(([action,ic,title,copy])=>`<button data-action="${action}"><span>${icon(ic,20)}</span><div><strong>${e(title)}</strong><small>${e(copy)}</small></div>${icon('chevron',14)}</button>`).join('')}</div>`;
  }

  function taskRow(t){const overdue=t.due_at&&new Date(t.due_at)<new Date();return `<button class="field-work-row ${overdue?'overdue':''}" data-action="field-open-entity" data-type="task" data-id="${e(t.id)}"><span>${icon(t.action_role==='approve'?'shield':t.action_role==='review'?'eye':'checkSquare',17)}</span><div><strong>${e(t.title)}</strong><small>${e(statusLabel(t.status))}${t.due_at?` · ${e(relativeTime(t.due_at))}`:''}</small></div><b class="priority-${e(t.priority||'medium')}">${e(priorityLabel(t.priority))}</b>${icon('chevron',13)}</button>`;}
  function drawingRow(d){return `<article class="field-drawing-row"><span class="field-drawing-icon">${icon('drafting',18)}</span><button data-action="field-open-drawing" data-id="${e(d.id)}"><strong>${e(d.drawing_no)} — ${e(d.title)}</strong><small>${d.cabinet_code?`${e(d.cabinet_code)} · `:''}${e(d.revision_code||L('بدون مراجعة','No revision'))} · ${e(statusLabel(d.revision_status||d.status))}${d.updated_at?` · ${e(relativeTime(d.updated_at))}`:''}</small></button><div>${caps().can_edit_takeoff?`<button class="icon-btn" data-action="field-open-takeoff" data-id="${e(d.id)}" title="${L('فتح الحصر','Open takeoff')}">${icon('fileSpreadsheet',15)}</button>`:''}<button class="icon-btn" data-action="field-open-drawing" data-id="${e(d.id)}" title="${L('فتح الرسم','Open drawing')}">${icon('chevron',15)}</button></div></article>`;}
  function documentRow(d){return `<button class="field-doc-row" data-action="field-open-entity" data-type="document" data-id="${e(d.id)}"><span>${icon(d.document_type==='photo'?'image':'file',16)}</span><div><strong>${e(d.display_name)}</strong><small>${e(statusLabel(d.control_status))}${d.revision_code?` · Rev ${e(d.revision_code)}`:''}${d.version_created_at?` · ${e(relativeTime(d.version_created_at))}`:''}</small></div>${icon('chevron',13)}</button>`;}
  function cabinetCard(c){const pct=readiness(c),latest=drawings().find(d=>d.cabinet_id===c.id);return `<article class="field-cabinet-card"><header><span>${icon('box',20)}</span><div><strong>${e(c.code)}</strong><small>${e(c.name)}</small></div><i class="field-status-dot"></i></header><div class="field-cabinet-progress"><div><span>${L('جاهزية الأدلة','Evidence readiness')}</span><b>${pct===null?L('غير محددة','Not set'):`${pct}%`}</b></div><span><i style="width:${pct||0}%"></i></span><small>${c.requirement_count?`${c.requirement_ready}/${c.requirement_count} ${L('متطلب مكتمل','requirements ready')}`:L('لا توجد متطلبات محددة','No configured requirements')}</small></div><div class="field-cabinet-facts"><span>${icon('drafting',13)} ${num(c.drawing_count)} ${L('رسم','drawings')}</span>${c.location_label?`<span>${icon('map',13)} ${e(c.location_label)}</span>`:''}</div><footer><button class="btn btn-secondary btn-sm" data-action="field-open-cabinet" data-id="${e(c.id)}">${L('فتح الكابينة','Open cabinet')}</button>${caps().can_upload&&c.root_folder_id?`<button class="btn btn-secondary btn-sm" data-action="field-upload" data-folder-id="${e(c.root_folder_id)}">${icon('camera',13)} ${L('دليل','Evidence')}</button>`:''}${latest?`<button class="btn btn-primary btn-sm" data-action="field-open-drawing" data-id="${e(latest.id)}">${icon('drafting',13)} ${L('الرسم','Drawing')}</button>`:caps().can_create_drawing?`<button class="btn btn-primary btn-sm" data-action="field-new-drawing" data-cabinet-id="${e(c.id)}">${icon('plus',13)} ${L('ارسم','Draw')}</button>`:''}</footer></article>`;}
  function siteSelector(){const sites=arr(local.snapshot?.sites);if(sites.length<=1)return `<div class="field-site-lock">${icon('map',15)}<span>${e(selectedSiteLabel())}</span></div>`;return `<label class="field-site-select">${icon('map',15)}<select data-field-site>${sites.map(s=>`<option value="${e(s.id)}" ${s.id===site()?.id?'selected':''}>${e(`${s.project_code} · ${s.code} — ${s.name}`)}</option>`).join('')}</select>${icon('chevronDown',13)}</label>`;}

  function executionMetric(iconName,value,label,tone=''){return `<article class="field-exec-metric ${tone}"><span>${icon(iconName,18)}</span><div><strong>${e(value)}</strong><small>${e(label)}</small></div></article>`;}
  function executionStrip(){const p=progress(),l=dailyLog(),eod=local.eod;return `<section class="field-execution-strip"><div class="field-execution-strip-head"><div><span class="eyebrow">${L('تنفيذ اليوم','TODAY EXECUTION')}</span><h3>${L('إيه اللي حصل فعلًا في الموقع؟','What actually happened on site?')}</h3><p>${L('Optimum يجمع المهام والرسومات والأدلة والفحوصات تلقائيًا، وأنت تضيف فقط الملاحظات الميدانية.','Optimum gathers tasks, drawings, evidence, and inspections automatically; you add only field notes.')}</p></div><label class="field-date-picker"><span>${icon('calendar',14)} ${L('يوم العمل','Work date')}</span><input type="date" data-field-date value="${e(local.workDate)}" max="${today()}" /></label></div><div class="field-exec-metrics">${executionMetric('checkSquare',num(p.tasks_done_today),L('مهام أُنجزت','Tasks done'),'success')}${executionMetric('shield',num(p.inspections_done),L('فحوصات','Inspections'),num(p.inspections_failed)?'warning':'')}${executionMetric('alert',num(p.issues_open),L('مشاكل مفتوحة','Open issues'),num(p.critical_issues)?'danger':'')}${executionMetric('pause',num(p.constraints_open),L('عوائق','Constraints'),num(p.constraints_open)?'warning':'')}${executionMetric('file',num(p.documents_added),L('أدلة مضافة','Evidence added'))}${executionMetric('drafting',num(p.drawings_changed),L('رسومات تغيرت','Drawings changed'))}</div><div class="field-execution-actions"><button class="btn btn-primary" data-action="field-daily-log">${icon('edit',14)} ${l?L('راجع سجل اليوم','Review daily log'):L('ابدأ سجل اليوم','Start daily log')}</button><button class="btn btn-secondary" data-action="field-end-day">${icon('checkSquare',14)} ${L('راجع نهاية اليوم','Review day')}</button><button class="btn btn-secondary" data-action="field-weekly">${icon('calendar',14)} ${L('ملخص الأسبوع','Weekly summary')}</button><span class="field-report-state ${e(l?.status||'draft')}">${icon(l?.status==='approved'?'check':'file',13)} ${e(l?statusLabel(l.status):L('لم يبدأ التقرير','Report not started'))}</span>${eod?`<span class="field-readiness-mini"><b>${eod.score}/${eod.total}</b>${L('جاهزية اليوم','day readiness')}</span>`:''}</div></section>`;}

  function inspectionRow(i){const failed=i.status==='failed',countFail=arr(i.items).filter(x=>x.result==='fail').length;return `<article class="field-execution-row"><span class="exec-row-icon ${failed?'danger':''}">${icon('shield',17)}</span><button data-action="field-open-inspection" data-id="${e(i.id)}"><strong>${e(i.title)}</strong><small>${e(statusLabel(i.status))}${countFail?` · ${countFail} ${L('بند لم يجتز','failed items')}`:''}${i.started_at?` · ${e(relativeTime(i.started_at))}`:''}</small></button><span class="badge ${failed?'badge-danger':'badge-info'}">${e(statusLabel(i.status))}</span></article>`;}
  function issueRow(i){return `<article class="field-execution-row"><span class="exec-row-icon severity-${e(i.severity)}">${icon('alert',17)}</span><button data-action="field-open-issue" data-id="${e(i.id)}"><strong>${e(i.title)}</strong><small>${e(severityLabel(i.severity))}${i.due_at?` · ${e(relativeTime(i.due_at))}`:''}${i.assigned_to?` · ${e(profileName(i.assigned_to))}`:''}</small></button><span class="badge">${e(statusLabel(i.status))}</span></article>`;}
  function constraintRow(c){return `<article class="field-execution-row"><span class="exec-row-icon warning">${icon('pause',17)}</span><button data-action="field-open-constraint" data-id="${e(c.id)}"><strong>${e(c.title)}</strong><small>${e(constraintLabel(c.constraint_type))}${c.impact?` · ${e(c.impact)}`:''}</small></button><span class="badge">${e(statusLabel(c.status))}</span></article>`;}

  function executionPanels(){return `<div class="field-execution-grid"><section class="field-section"><header><div><span class="eyebrow">${L('الفحوصات','INSPECTIONS')}</span><h3>${L('فحوصات اليوم والجودة','Field checks & quality')}</h3></div>${execCaps().can_edit?`<button class="btn btn-primary btn-sm" data-action="field-new-inspection">${icon('plus',13)} ${L('فحص جديد','New inspection')}</button>`:''}</header><div class="field-execution-list">${inspections().length?inspections().slice(0,6).map(inspectionRow).join(''):emptyState('shield',L('لا توجد فحوصات حديثة','No recent inspections'),L('ابدأ من قالب بسيط وسجل نتيجة كل بند.','Start from a simple template and record each result.'))}</div></section><section class="field-section"><header><div><span class="eyebrow">${L('المشاكل','ISSUES / SNAGS')}</span><h3>${L('المشاكل التي تمنع الإغلاق','Issues blocking closeout')}</h3></div>${execCaps().can_edit?`<button class="btn btn-primary btn-sm" data-action="field-new-issue">${icon('plus',13)} ${L('مشكلة جديدة','New issue')}</button>`:''}</header><div class="field-execution-list">${issues().length?issues().slice(0,6).map(issueRow).join(''):emptyState('check',L('لا توجد مشاكل مفتوحة','No open issues'),L('أي مشكلة ميدانية تسجل هنا وتظل مرتبطة بسياقها.','Field issues appear here and keep their project/site context.'))}</div></section><section class="field-section"><header><div><span class="eyebrow">${L('العوائق','CONSTRAINTS')}</span><h3>${L('ليه الشغل متعطل؟','What is blocking progress?')}</h3></div>${execCaps().can_edit?`<button class="btn btn-primary btn-sm" data-action="field-new-constraint">${icon('plus',13)} ${L('سجل عائق','Log constraint')}</button>`:''}</header><div class="field-execution-list">${constraints().length?constraints().slice(0,6).map(constraintRow).join(''):emptyState('check',L('لا توجد عوائق مفتوحة','No open constraints'),L('لو الشغل وقف بسبب مادة أو تصريح أو تصميم، سجله هنا بدل ما يضيع في التعليقات.','When work stops because of material, permit, or design, record it here instead of losing it in comments.'))}</div></section></div>`;}

  function page(){
    if(local.loading&&!local.snapshot)return `<div class="field-loading"><span class="spinner"></span><strong>${L('نجهز موقعك…','Preparing your site…')}</strong><small>${L('نجمع المهام والرسومات والكبائن والملفات والتنفيذ اليومي في مكان واحد.','Bringing tasks, drawings, cabinets, files, and daily execution together.')}</small></div>`;
    if(!local.snapshot?.site)return `${pageHeader(L('مساحة مشرف الموقع','Site Supervisor Workspace'),L('واجهة تنفيذ ميدانية للرسم والحصر والملفات والمهام والتقرير اليومي.','A field execution workspace for drawings, takeoff, files, tasks, and daily reporting.'),`<button class="btn btn-secondary" data-action="field-refresh">${icon('refresh',14)} ${L('تحديث','Refresh')}</button>`)}${emptyState('map',L('لا يوجد موقع متاح لحسابك','No site is available to your account'),L('اطلب من الأدمن ربط دور مشرف الموقع بنطاق مشروع أو موقع.','Ask an admin to scope the Site Supervisor role to a project or site.'))}`;
    const s=site(),p=project(),st=local.snapshot.stats||{},next=nextAction(),reqPct=st.requirements_total?Math.round(num(st.requirements_ready)/Math.max(1,num(st.requirements_total))*100):0;
    return `${pageHeader(L('مساحة مشرف الموقع','Site Supervisor Workspace'),L('الرسم والحصر والتنفيذ والفحوصات والأدلة والتقرير اليومي — كلهم في سياق الموقع نفسه.','Drawing, takeoff, execution, inspections, evidence, and daily reporting — all in the same site context.'),`<button class="btn btn-secondary" data-action="field-refresh" ${local.refreshing?'disabled':''}>${icon('refresh',14)} ${local.refreshing?L('جارٍ التحديث…','Refreshing…'):L('تحديث','Refresh')}</button>`)}<section class="field-hero"><div class="field-hero-copy"><span class="eyebrow">${L('تنفيذ الموقع','FIELD EXECUTION')}</span><div class="field-hero-title"><span>${icon('hardHat',30)}</span><div><h2>${L('كل يوم الموقع في مكان واحد','Your whole site day in one place')}</h2><p>${e(`${p.code} — ${p.name} · ${s.code} — ${s.name}`)}</p></div></div>${siteSelector()}<div class="field-role-note">${icon('info',15)}<span><strong>${L('مشرف الموقع ينفذ ويوثق','The Site Supervisor executes and documents')}</strong><small>${L('ارسم، اعمل الحصر، نفذ الفحص، سجل المشكلة وارفع الدليل. Optimum يجمع النشاط تلقائيًا في تقرير اليوم.','Draw, take off, inspect, log issues, and upload evidence. Optimum composes the day report automatically.')}</small></span></div></div><div class="field-metrics">${metric('checkSquare',st.tasks_today||0,L('مهام اليوم','Due today'),st.tasks_overdue?'danger':'')}${metric('alert',st.tasks_overdue||0,L('متأخرة','Overdue'),st.tasks_overdue?'danger':'')}${metric('box',st.cabinets||0,L('كابينة','Cabinets'))}${metric('drafting',st.drawings||0,L('رسومات','Drawings'))}${metric('shield',`${reqPct}%`,L('جاهزية الأدلة','Evidence ready'),reqPct===100?'success':'')}</div></section>${executionStrip()}<section class="field-next ${next.tone}"><span>${icon(next.icon,21)}</span><div><small>${L('الخطوة المقترحة الآن','SUGGESTED NEXT STEP')}</small><strong>${e(next.title)}</strong><p>${e(next.copy)}</p></div><button class="btn btn-primary" ${next.action}>${L('ابدأ الآن','Start now')} ${icon('arrowLeft',14)}</button></section><section class="field-section field-actions"><header><div><span class="eyebrow">${L('اختصارات الموقع','SITE SHORTCUTS')}</span><h3>${L('نفذ وسجل من نفس المكان','Execute and record from the same place')}</h3><p>${L('كل إجراء يرث المشروع والموقع تلقائيًا ويرجع أثره للتقرير اليومي ومركز التشغيل.','Every action inherits project/site context and feeds the daily report and Operations Center.')}</p></div></header>${quickActions()}</section>${executionPanels()}<div class="field-main-grid"><section class="field-section"><header><div><span class="eyebrow">${L('شغلي اليوم','MY SITE WORK')}</span><h3>${L('المهام التي تخصك في هذا الموقع','Your work in this site')}</h3></div><button class="btn btn-ghost btn-sm" data-nav="tasks">${L('كل المهام','All tasks')}</button></header><div class="field-work-list">${tasks().length?tasks().slice(0,8).map(taskRow).join(''):emptyState('checkSquare',L('لا توجد مهام مفتوحة لك هنا','No open work for you here'),L('أي مهمة تُسند لك في هذا الموقع ستظهر هنا فورًا.','Any work assigned to you at this site appears here immediately.'))}</div></section><section class="field-section field-drawings"><header><div><span class="eyebrow">${L('الرسم والحصر','DRAWING & TAKEOFF')}</span><h3>${L('آخر رسومات الموقع','Latest site drawings')}</h3></div><button class="btn btn-ghost btn-sm" data-nav="engineering">${L('كل الرسومات','All drawings')}</button></header><div class="field-drawing-list">${drawings().length?drawings().slice(0,7).map(drawingRow).join(''):emptyState('drafting',L('لا توجد رسومات بعد','No drawings yet'),caps().can_create_drawing?L('ابدأ أول رسم؛ سيتم ربطه بالموقع وحفظه داخل CDE تلقائيًا.','Create the first drawing; it will be site-linked and synced to CDE automatically.'):L('لا توجد رسومات متاحة ضمن نطاقك.','No drawings are available in your scope.'),caps().can_create_drawing?`<button class="btn btn-primary" data-action="field-new-drawing">${icon('plus',14)} ${L('رسم جديد','New drawing')}</button>`:'')}</div></section></div><section class="field-section"><header><div><span class="eyebrow">${L('الكبائن','CABINETS')}</span><h3>${L('افتح الكابينة واشتغل من سياقها','Open a cabinet and work in its context')}</h3></div></header><div class="field-cabinet-grid">${cabinets().length?cabinets().map(cabinetCard).join(''):emptyState('box',L('لا توجد كبائن في هذا الموقع','No cabinets in this site'),L('الكبائن التي يضيفها فريق المشروع ستظهر هنا.','Cabinets added by the project team appear here.'))}</div></section><section class="field-section field-files"><header><div><span class="eyebrow">${L('آخر الملفات','RECENT SITE FILES')}</span><h3>${L('الأدلة والملفات التي وصلتك حديثًا','Recent evidence and files')}</h3></div><button class="btn btn-ghost btn-sm" data-action="field-open-files">${L('مساحة الملفات','Files Workspace')}</button></header><div class="field-doc-list">${docs().length?docs().slice(0,8).map(documentRow).join(''):emptyState('folder',L('لا توجد ملفات حديثة','No recent files'),L('ارفع صورة أو شهادة وسيتم حفظها في CDE.','Upload a photo or certificate and it will be stored in CDE.'))}</div></section>`;
  }

  function dailyReportHtml(snapshot=exec()){
    const l=snapshot.daily_log||{},p=snapshot.progress||{},s=snapshot.site||site()||{},pr=snapshot.project||project()||{},completed=arr(snapshot.completed_tasks),docsToday=arr(snapshot.documents_today),drawingsToday=arr(snapshot.drawings_today),ins=arr(snapshot.inspections),iss=arr(snapshot.issues),cons=arr(snapshot.constraints);
    const esc=(x)=>e(x||'—');
    return `<!doctype html><html lang="${state.prefs?.locale||'ar'}" dir="${state.prefs?.locale==='en'?'ltr':'rtl'}"><meta charset="utf-8"><title>${esc(L('تقرير الموقع اليومي','Daily Site Report'))}</title><style>body{font-family:Arial,sans-serif;margin:36px;color:#172033}h1{font-size:24px;margin:0 0 6px}h2{font-size:16px;margin:24px 0 10px}.meta,.stats{display:flex;gap:10px;flex-wrap:wrap}.box{border:1px solid #d8e0e8;border-radius:10px;padding:10px 12px}.stats .box{min-width:110px}.box b{display:block;font-size:18px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #d8e0e8;padding:7px;text-align:start}th{background:#f3f6f9}.note{white-space:pre-wrap;border:1px solid #d8e0e8;border-radius:10px;padding:12px;min-height:40px}</style><h1>${esc(L('تقرير الموقع اليومي','Daily Site Report'))}</h1><div class="meta"><span class="box">${esc(pr.code)} — ${esc(pr.name)}</span><span class="box">${esc(s.code)} — ${esc(s.name)}</span><span class="box">${esc(local.workDate)}</span><span class="box">${esc(statusLabel(l.status||'draft'))}</span></div><h2>${esc(L('ملخص اليوم','Day summary'))}</h2><div class="stats"><span class="box"><b>${num(p.tasks_done_today)}</b>${esc(L('مهام مكتملة','Tasks done'))}</span><span class="box"><b>${num(p.inspections_done)}</b>${esc(L('فحوصات','Inspections'))}</span><span class="box"><b>${num(p.issues_open)}</b>${esc(L('مشاكل مفتوحة','Open issues'))}</span><span class="box"><b>${num(p.documents_added)}</b>${esc(L('أدلة مضافة','Evidence added'))}</span><span class="box"><b>${num(p.drawings_changed)}</b>${esc(L('رسومات محدثة','Drawings changed'))}</span></div><h2>${esc(L('ما تم تنفيذه','Work completed'))}</h2><div class="note">${esc(l.work_completed||l.summary)}</div><h2>${esc(L('خطة الغد','Tomorrow plan'))}</h2><div class="note">${esc(l.tomorrow_plan)}</div><h2>${esc(L('السلامة والطقس','Safety & weather'))}</h2><div class="note">${esc(l.safety_note)}<br>${esc(l.weather_note)}</div><h2>${esc(L('العناصر الميدانية','Field activity'))}</h2><table><thead><tr><th>${esc(L('النوع','Type'))}</th><th>${esc(L('التفصيل','Details'))}</th><th>${esc(L('الحالة','Status'))}</th></tr></thead><tbody>${completed.map(x=>`<tr><td>${esc(L('مهمة','Task'))}</td><td>${esc(x.title)}</td><td>${esc(L('مكتملة','Completed'))}</td></tr>`).join('')}${drawingsToday.map(x=>`<tr><td>${esc(L('رسم','Drawing'))}</td><td>${esc(`${x.drawing_no} — ${x.title}`)}</td><td>${esc(statusLabel(x.status))}</td></tr>`).join('')}${docsToday.map(x=>`<tr><td>${esc(L('دليل/ملف','Evidence / file'))}</td><td>${esc(x.display_name)}</td><td>${esc(L('مضاف اليوم','Added today'))}</td></tr>`).join('')}${ins.filter(x=>String(x.completed_at||'').slice(0,10)===local.workDate).map(x=>`<tr><td>${esc(L('فحص','Inspection'))}</td><td>${esc(x.title)}</td><td>${esc(statusLabel(x.status))}</td></tr>`).join('')}${iss.map(x=>`<tr><td>${esc(L('مشكلة','Issue'))}</td><td>${esc(x.title)}</td><td>${esc(statusLabel(x.status))}</td></tr>`).join('')}${cons.map(x=>`<tr><td>${esc(L('عائق','Constraint'))}</td><td>${esc(x.title)}</td><td>${esc(statusLabel(x.status))}</td></tr>`).join('')}</tbody></table></html>`;
  }

  async function syncDailyReportToCde({silent=false}={}){
    const l=dailyLog();if(!l?.id||!exec().report_folder_id||!execCaps().can_upload)return false;
    const html=dailyReportHtml(),blob=new Blob([html],{type:'text/html;charset=utf-8'}),safeSite=String(site()?.code||'SITE').replace(/[^a-zA-Z0-9._-]/g,'_'),filename=`${safeSite}_${local.workDate}_DAILY_REPORT.html`,existing=l.report_document_id?{id:l.report_document_id}:null;let reservation,uploaded=false;
    try{
      reservation=existing?await api.rpc('begin_new_version_upload_v2',{p_document_id:existing.id,p_original_filename:filename,p_mime_type:blob.type,p_size_bytes:blob.size,p_change_note:L('تحديث تلقائي للتقرير اليومي','Automatic daily report update'),p_revision_code:local.workDate,p_restored_from_version_id:null}):await api.rpc('begin_document_upload_v2',{p_folder_id:exec().report_folder_id,p_display_name:`${L('تقرير الموقع اليومي','Daily Site Report')} — ${site()?.code||''} — ${local.workDate}`,p_original_filename:filename,p_mime_type:blob.type,p_size_bytes:blob.size,p_document_type:'report',p_description:L('تقرير يومي مولد من نشاط الموقع الحقيقي داخل Optimum.','Daily report generated from actual site activity in Optimum.'),p_tags:['site-daily-report',`site:${site()?.id}`,`date:${local.workDate}`],p_change_note:L('تقرير يومي تلقائي','Automatic daily report'),p_discipline:null,p_revision_code:local.workDate,p_document_date:local.workDate,p_expires_at:null,p_issuer:state.company?.name||'Optimum'});
      await api.uploadObject(reservation.storage_bucket,reservation.storage_path,blob);uploaded=true;await api.rpc('finalize_document_upload',{p_version_id:reservation.version_id,p_checksum_sha256:null});const docId=existing?.id||reservation.document_id;await api.rpc('link_site_daily_report_document',{p_log_id:l.id,p_document_id:docId});if(local.execution?.daily_log)local.execution.daily_log.report_document_id=docId;if(!silent)toast('success',L('تم حفظ التقرير داخل مساحة الملفات مع الاحتفاظ بالإصدارات','Report saved in Files Workspace with version history'));return true;
    }catch(err){if(uploaded&&reservation)try{await api.deleteObject(reservation.storage_bucket,reservation.storage_path);}catch{}if(reservation)try{await api.rpc('abort_document_upload',{p_version_id:reservation.version_id});}catch{}if(!silent)formError(err,L('تم حفظ بيانات اليوم لكن تعذر حفظ نسخة التقرير في الملفات','Day data was saved, but the report file could not be synced'));return false;}
  }

  function openDailyLog(){
    const l=dailyLog()||local.offlineDraft||{},p=progress(),readonly=l.status==='approved'||(!execCaps().can_edit&&l.status==='submitted');
    openDrawer({title:L('سجل الموقع اليومي','Daily Site Log'),subtitle:`${e(selectedSiteLabel())} · ${e(formatDate(local.workDate))}`,wide:true,body:`<form class="field-daily-form" data-form="field-daily-log"><section class="field-report-compose-hero"><div><span class="eyebrow">${L('التقرير يتكون تلقائيًا','AUTO-COMPOSED REPORT')}</span><h3>${L('Optimum جمع نشاط اليوم — أضف فقط اللي مش موجود في النظام','Optimum collected today’s activity — add only what the system cannot know')}</h3><p>${L('المهام والرسومات والفحوصات والملفات تتسحب من مصادرها الأصلية. الملاحظات البشرية هنا فقط.','Tasks, drawings, inspections, and files come from their original sources. Only human field notes belong here.')}</p></div><div class="field-report-live-stats">${executionMetric('checkSquare',num(p.tasks_done_today),L('مهام مكتملة','Tasks done'))}${executionMetric('file',num(p.documents_added),L('أدلة','Evidence'))}${executionMetric('shield',num(p.inspections_done),L('فحوصات','Inspections'))}</div></section><div class="form-grid cols-2"><div class="form-row span-2"><label>${L('ملخص اليوم','Day summary')}</label><textarea class="textarea" name="summary" rows="3" ${readonly?'readonly':''}>${e(l.summary||'')}</textarea><small>${L('جملة أو اثنتان تلخصان حالة اليوم، بدون نسخ تفاصيل المهام.','One or two sentences summarizing the day; do not copy task details.')}</small></div><div class="form-row"><label>${L('ما تم تنفيذه خارج المهام المسجلة','Work completed outside tracked tasks')}</label><textarea class="textarea" name="work_completed" rows="5" ${readonly?'readonly':''}>${e(l.work_completed||'')}</textarea></div><div class="form-row"><label>${L('خطة الغد','Tomorrow plan')}</label><textarea class="textarea" name="tomorrow_plan" rows="5" ${readonly?'readonly':''}>${e(l.tomorrow_plan||'')}</textarea></div><div class="form-row"><label>${L('ملاحظة السلامة','Safety note')}</label><textarea class="textarea" name="safety_note" rows="3" ${readonly?'readonly':''}>${e(l.safety_note||'')}</textarea></div><div class="form-row"><label>${L('الطقس / ظروف العمل','Weather / work conditions')}</label><textarea class="textarea" name="weather_note" rows="3" ${readonly?'readonly':''}>${e(l.weather_note||'')}</textarea></div><div class="form-row"><label>${L('القوى العاملة — عدد الفريق','Crew count')}</label><input class="input" name="crew_count" type="number" min="0" value="${e(l.manpower?.crew_count??'')}" ${readonly?'readonly':''}/></div><div class="form-row"><label>${L('ساعات العمل','Working hours')}</label><input class="input" name="work_hours" type="number" min="0" step="0.5" value="${e(l.manpower?.work_hours??'')}" ${readonly?'readonly':''}/></div></div>${local.offlineDraft?`<div class="alert alert-warning">${icon('info',14)}<div class="alert-copy"><strong>${L('وجدنا مسودة محفوظة على هذا الجهاز','A local draft was found on this device')}</strong><p>${L('تم الاحتفاظ بها لأن الاتصال كان غير متاح أو قبل الحفظ الأخير.','It was kept because the connection was unavailable or before the last save.')}</p></div></div>`:''}<div class="field-report-footer"><span>${icon('file',14)} ${l.report_document_id?L('نسخة التقرير موجودة في مساحة الملفات','Report copy is stored in Files Workspace'):L('بعد الحفظ سيتم إنشاء نسخة داخل مساحة الملفات','A Files Workspace copy will be created after save')}</span>${readonly?'':`<button class="btn btn-secondary" type="submit" data-save-only="1">${icon('save',14)} ${L('حفظ المسودة','Save draft')}</button>`}${!readonly&&['draft','returned',undefined].includes(l.status)?`<button class="btn btn-primary" type="button" data-action="field-submit-day">${icon('send',14)} ${L('حفظ وإرسال للمراجعة','Save & submit for review')}</button>`:''}${execCaps().can_review_report&&l.status==='submitted'?`<button class="btn btn-secondary" type="button" data-action="field-return-day">${L('إرجاع بملاحظة','Return with note')}</button><button class="btn btn-primary" type="button" data-action="field-approve-day">${icon('check',14)} ${L('اعتماد التقرير','Approve report')}</button>`:''}</div></form>`});
  }

  async function openInspectionEditor(id=null){
    const current=id?inspections().find(x=>x.id===id):null,templates=arr(exec().templates),items=arr(current?.items),canEdit=execCaps().can_edit&&!['passed','closed'].includes(current?.status);
    let evidenceDocs=[];if(current&&execCaps().can_upload){try{const rows=await api.rpc('document_picker_query',{p_company_id:state.companyId,p_project_id:project()?.id||null,p_site_id:site()?.id||null,p_query:'',p_limit:120});evidenceDocs=arr(rows);}catch{evidenceDocs=[];}}
    if(!current){openDialog({title:L('ابدأ فحصًا ميدانيًا','Start a field inspection'),subtitle:L('اختر قالبًا بسيطًا، ثم سجل Pass / Fail / N/A لكل بند.','Choose a simple template, then record Pass / Fail / N/A for each item.'),body:`<form class="form-grid" data-form="field-inspection-create"><div class="form-row"><label>${L('قالب الفحص','Inspection template')}</label><select class="select" name="template_id" required><option value="">${L('اختر قالبًا','Choose a template')}</option>${templates.map(t=>`<option value="${e(t.id)}">${e(state.prefs.locale==='ar'?t.name_ar:t.name_en)}</option>`).join('')}</select></div><div class="form-row"><label>${L('الكابينة — اختيارية','Cabinet — optional')}</label><select class="select" name="cabinet_id"><option value="">—</option>${cabinets().map(c=>`<option value="${e(c.id)}">${e(c.code)} — ${e(c.name)}</option>`).join('')}</select></div><div class="form-row"><label>${L('عنوان مخصص — اختياري','Custom title — optional')}</label><input class="input" name="title" /></div><button class="btn btn-primary" type="submit">${icon('play',14)} ${L('ابدأ الفحص','Start inspection')}</button></form>`});return;}
    const evidenceOptions=(selected)=>`<option value="">${L('بدون دليل مرتبط','No linked evidence')}</option>${evidenceDocs.map(d=>`<option value="${e(d.id)}" ${d.id===selected?'selected':''}>${e(d.display_name||d.system_code||L('مستند','Document'))}</option>`).join('')}`;
    openDrawer({title:current.title,subtitle:`${e(statusLabel(current.status))} · ${e(formatDateTime(current.started_at))}`,wide:true,body:`<form class="field-inspection-form" data-form="field-inspection-save" data-id="${e(current.id)}"><div class="field-inspection-evidence-guide">${icon('camera',18)}<div><strong>${L('الدليل يظل داخل مساحة الملفات','Evidence stays in Files Workspace')}</strong><small>${L('ارفع الصورة أو الشهادة مرة واحدة في CDE ثم اربطها ببند الفحص؛ لا ننشئ نسخة ثانية.','Upload the photo or certificate once to CDE, then link it to the inspection item; no duplicate file is created.')}</small></div>${canEdit?`<button class="btn btn-secondary btn-sm" type="button" data-action="field-upload">${icon('upload',13)} ${L('رفع دليل جديد','Upload evidence')}</button>`:''}</div><div class="field-inspection-items">${items.map((it,idx)=>`<article class="field-inspection-item ${e(it.result)}"><div><span>${idx+1}</span><strong>${e(state.prefs.locale==='ar'?it.label_ar:it.label_en)}</strong></div><div class="segmented compact"><button type="button" data-action="field-inspection-result" data-key="${e(it.item_key)}" data-result="pass" class="${it.result==='pass'?'active':''}">${L('ناجح','Pass')}</button><button type="button" data-action="field-inspection-result" data-key="${e(it.item_key)}" data-result="fail" class="${it.result==='fail'?'active':''}">${L('لم يجتز','Fail')}</button><button type="button" data-action="field-inspection-result" data-key="${e(it.item_key)}" data-result="na" class="${it.result==='na'?'active':''}">${L('لا ينطبق','N/A')}</button></div><textarea class="textarea" rows="2" data-inspection-note="${e(it.item_key)}" placeholder="${L('ملاحظة مختصرة عند الحاجة','Short note if needed')}" ${canEdit?'':'readonly'}>${e(it.note||'')}</textarea><label class="field-inspection-evidence"><span>${icon('file',13)} ${L('دليل مرتبط','Linked evidence')}</span><select class="select" data-inspection-evidence="${e(it.item_key)}" ${canEdit?'':'disabled'}>${evidenceOptions(it.evidence_document_id||'')}</select></label></article>`).join('')}</div><div class="form-row"><label>${L('ملاحظة الفحص العامة','Overall inspection note')}</label><textarea class="textarea" name="overall_note" rows="3" ${canEdit?'':'readonly'}>${e(current.overall_note||'')}</textarea></div>${canEdit?`<div class="dialog-actions"><button class="btn btn-secondary" type="submit">${icon('save',14)} ${L('حفظ','Save')}</button><button class="btn btn-primary" type="button" data-action="field-complete-inspection" data-id="${e(current.id)}">${icon('check',14)} ${L('إنهاء الفحص','Complete inspection')}</button></div>`:''}</form>`});
  }

  function openIssueEditor(id=null){const x=id?issues().find(i=>i.id===id):null;if(x){openDrawer({title:x.title,subtitle:`${e(severityLabel(x.severity))} · ${e(statusLabel(x.status))}`,body:`<div class="field-issue-detail"><div class="field-detail-facts"><span>${icon('alert',14)} ${e(severityLabel(x.severity))}</span>${x.assigned_to?`<span>${icon('users',14)} ${e(profileName(x.assigned_to))}</span>`:''}${x.due_at?`<span>${icon('calendar',14)} ${e(formatDateTime(x.due_at))}</span>`:''}</div><p>${e(x.description||L('لا يوجد وصف إضافي.','No additional description.'))}</p>${execCaps().can_edit?`<div class="drawer-action-grid"><button class="btn btn-secondary" data-action="field-issue-status" data-id="${e(x.id)}" data-status="in_progress">${L('بدء المعالجة','Start work')}</button><button class="btn btn-secondary" data-action="field-issue-status" data-id="${e(x.id)}" data-status="ready_for_review">${L('جاهزة للمراجعة','Ready for review')}</button><button class="btn btn-primary" data-action="field-issue-close" data-id="${e(x.id)}">${L('إغلاق المشكلة','Close issue')}</button></div>`:''}</div>`});return;}openDialog({title:L('مشكلة ميدانية جديدة','New field issue'),subtitle:L('سجل المشكلة في مكانها بدل ما تضيع في واتساب أو التعليقات.','Record the issue in context instead of losing it in chats or comments.'),body:`<form class="form-grid" data-form="field-issue"><div class="form-row"><label>${L('المشكلة','Issue')}</label><input class="input" name="title" required /></div><div class="form-row"><label>${L('الوصف','Description')}</label><textarea class="textarea" name="description" rows="4"></textarea></div><div class="form-grid cols-2"><div class="form-row"><label>${L('الدرجة','Severity')}</label><select class="select" name="severity"><option value="medium">${L('متوسطة','Medium')}</option><option value="high">${L('عالية','High')}</option><option value="critical">${L('حرجة','Critical')}</option><option value="low">${L('منخفضة','Low')}</option></select></div><div class="form-row"><label>${L('الكابينة','Cabinet')}</label><select class="select" name="cabinet_id"><option value="">—</option>${cabinets().map(c=>`<option value="${e(c.id)}">${e(c.code)} — ${e(c.name)}</option>`).join('')}</select></div></div><div class="form-row"><label>${L('المكان / الوصف المكاني','Location note')}</label><input class="input" name="location_note" /></div><button class="btn btn-primary" type="submit">${icon('plus',14)} ${L('تسجيل المشكلة','Log issue')}</button></form>`});}

  function openConstraintEditor(id=null){const x=id?constraints().find(c=>c.id===id):null;if(x){openDrawer({title:x.title,subtitle:`${e(constraintLabel(x.constraint_type))} · ${e(statusLabel(x.status))}`,body:`<div class="field-issue-detail"><div class="field-detail-facts"><span>${icon('pause',14)} ${e(constraintLabel(x.constraint_type))}</span></div><p>${e(x.description||'')}</p>${x.impact?`<div class="alert alert-warning"><div class="alert-copy"><strong>${L('الأثر على التنفيذ','Impact')}</strong><p>${e(x.impact)}</p></div></div>`:''}${execCaps().can_edit?`<button class="btn btn-primary" data-action="field-resolve-constraint" data-id="${e(x.id)}">${icon('check',14)} ${L('تم حل العائق','Resolve constraint')}</button>`:''}</div>`});return;}openDialog({title:L('سجل عائقًا','Log a constraint'),subtitle:L('حدد سبب التعطيل وتأثيره حتى يعرف المدير لماذا يتأخر التنفيذ.','Record the blocker and its impact so the manager knows why progress is delayed.'),body:`<form class="form-grid" data-form="field-constraint"><div class="form-row"><label>${L('نوع العائق','Constraint type')}</label><select class="select" name="constraint_type"><option value="material">${L('مواد','Material')}</option><option value="permit">${L('تصريح','Permit')}</option><option value="design">${L('تصميم','Design')}</option><option value="access">${L('وصول','Access')}</option><option value="client">${L('العميل','Client')}</option><option value="weather">${L('طقس','Weather')}</option><option value="technical">${L('فني','Technical')}</option><option value="resource">${L('موارد','Resources')}</option><option value="other">${L('أخرى','Other')}</option></select></div><div class="form-row"><label>${L('العنوان','Title')}</label><input class="input" name="title" required /></div><div class="form-row"><label>${L('التفاصيل','Details')}</label><textarea class="textarea" name="description" rows="3"></textarea></div><div class="form-row"><label>${L('الأثر على الشغل','Impact on work')}</label><textarea class="textarea" name="impact" rows="3"></textarea></div><button class="btn btn-primary" type="submit">${icon('plus',14)} ${L('حفظ العائق','Save constraint')}</button></form>`});}

  async function openEndOfDay(){await loadExecution({force:true,silent:true});const r=local.eod||{},checks=arr(r.checks),labels={log:L('سجل اليوم موجود','Daily log exists'),work:L('تم توثيق العمل','Work is documented'),critical:L('لا توجد مشكلة حرجة مفتوحة','No critical issue is open'),inspection:L('لا يوجد فحص فاشل اليوم','No failed inspection today'),evidence:L('يوجد أثر عمل موثق','Work evidence exists'),tomorrow:L('خطة الغد مكتوبة','Tomorrow plan is written'),submit:L('التقرير أُرسل أو اعتُمد','Report submitted or approved')};openDrawer({title:L('مراجعة نهاية اليوم','End-of-day review'),subtitle:`${e(selectedSiteLabel())} · ${e(formatDate(local.workDate))}`,wide:true,body:`<section class="field-eod-hero"><div><span class="eyebrow">${L('جاهزية اليوم','DAY READINESS')}</span><h2>${e(r.score||0)}/${e(r.total||7)}</h2><p>${L('مش مطلوب تكتب تقرير من الصفر؛ أكمل النقاط الناقصة فقط.','You do not need to write a report from scratch; complete only the missing checks.')}</p></div><div class="field-eod-ring"><strong>${e(r.percent||0)}%</strong></div></section><div class="field-eod-checks">${checks.map(c=>`<article class="${c.done?'done':'missing'}"><span>${icon(c.done?'check':'alert',16)}</span><div><strong>${e(labels[c.key]||c.key)}</strong><small>${c.done?L('مكتملة','Complete'):L('تحتاج إجراء','Needs action')}</small></div>${!c.done&&c.key==='log'?`<button class="btn btn-secondary btn-sm" data-action="field-daily-log">${L('افتح السجل','Open log')}</button>`:!c.done&&c.key==='tomorrow'?`<button class="btn btn-secondary btn-sm" data-action="field-daily-log">${L('أضف خطة الغد','Add plan')}</button>`:!c.done&&c.key==='submit'?`<button class="btn btn-secondary btn-sm" data-action="field-daily-log">${L('راجع التقرير','Review report')}</button>`:''}</article>`).join('')}</div><div class="field-eod-summary"><h3>${L('ما جمعه Optimum تلقائيًا','What Optimum collected automatically')}</h3><div class="field-exec-metrics">${executionMetric('checkSquare',num(progress().tasks_done_today),L('مهام أُنجزت','Tasks done'))}${executionMetric('drafting',num(progress().drawings_changed),L('رسومات تغيرت','Drawings changed'))}${executionMetric('file',num(progress().documents_added),L('أدلة جديدة','New evidence'))}${executionMetric('shield',num(progress().inspections_done),L('فحوصات','Inspections'))}</div></div>`});}

  async function openWeekly(){const d=new Date(local.workDate+'T12:00:00'),day=d.getDay(),diff=(day+6)%7,start=new Date(d);start.setDate(d.getDate()-diff);const weekStart=start.toISOString().slice(0,10);if(!local.weekly||local.weekly.week_start!==weekStart)local.weekly=await api.rpc('site_weekly_progress',{p_company_id:state.companyId,p_site_id:local.siteId,p_week_start:weekStart});const w=local.weekly||{},s=w.summary||{};openDrawer({title:L('ملخص تقدم الأسبوع','Weekly Progress Summary'),subtitle:`${e(formatDate(w.week_start))} — ${e(formatDate(w.week_end))}`,wide:true,body:`<div class="field-weekly-metrics">${executionMetric('checkSquare',num(s.tasks_done),L('مهام أُنجزت','Tasks done'))}${executionMetric('shield',num(s.inspections),L('فحوصات','Inspections'))}${executionMetric('alert',num(s.issues_created),L('مشاكل ظهرت','Issues created'))}${executionMetric('check',num(s.issues_closed),L('مشاكل أُغلقت','Issues closed'))}${executionMetric('file',num(s.documents_added),L('أدلة مضافة','Evidence added'))}${executionMetric('send',num(s.approved_reports),L('تقارير معتمدة','Approved reports'))}</div><div class="field-week-grid">${arr(w.days).map(d=>`<article><header><strong>${e(formatDate(d.date))}</strong><span class="badge">${e(statusLabel(d.report_status||'draft'))}</span></header><div><span>${icon('checkSquare',13)} ${d.tasks_done}</span><span>${icon('shield',13)} ${d.inspections}</span><span>${icon('alert',13)} ${d.issues_created}</span><span>${icon('file',13)} ${d.documents}</span></div></article>`).join('')}</div>`});}

  function help(){return [L('ابدأ من “تنفيذ اليوم”: Optimum يجمع تلقائيًا المهام والرسومات والأدلة والفحوصات الخاصة بتاريخ العمل.','Start from Today Execution: Optimum automatically gathers tasks, drawings, evidence, and inspections for the work date.'),L('استخدم الفحص للمراجعة الميدانية المنظمة، والمشكلة للـSnag، والعائق لتسجيل سبب توقف التنفيذ.','Use Inspections for structured checks, Issues for snags, and Constraints to record why work is blocked.'),L('لا تكتب التقرير اليومي من الصفر؛ افتح سجل اليوم وأضف فقط الملخص وخطة الغد وما لم يعرفه النظام.','Do not write the daily report from scratch; add only the summary, tomorrow plan, and information the system cannot know.'),L('الرسم والحصر والتقرير اليومي والأدلة تُحفظ في CDE بالإصدارات، وكل شيء يظل مرتبطًا بالمشروع والموقع.','Drawing, takeoff, daily report, and evidence are versioned in CDE and remain linked to project/site context.')];}

  async function saveDailyForm(form,{submit=false}={}){
    const data=Object.fromEntries(new FormData(form).entries()),payload={summary:data.summary||null,work_completed:data.work_completed||null,tomorrow_plan:data.tomorrow_plan||null,safety_note:data.safety_note||null,weather_note:data.weather_note||null,manpower:{crew_count:data.crew_count===''?null:Number(data.crew_count),work_hours:data.work_hours===''?null:Number(data.work_hours)},equipment:[]};
    localStorage.setItem(offlineDraftKey(),JSON.stringify(payload));local.offlineDraft=payload;
    if(!navigator.onLine){toast('info',L('الاتصال غير متاح — حفظنا المسودة على الجهاز وسنحتاج مزامنتها عند عودة الشبكة','You are offline — the draft is saved on this device and can be synced when connection returns'));return false;}
    let l=dailyLog();if(!l)l=await api.rpc('ensure_site_daily_log',{p_company_id:state.companyId,p_site_id:local.siteId,p_log_date:local.workDate});await api.rpc('save_site_daily_log',{p_log_id:l.id,p_payload:payload});localStorage.removeItem(offlineDraftKey());local.offlineDraft=null;await loadExecution({force:true,silent:true});await syncDailyReportToCde({silent:true});if(submit){await api.rpc('submit_site_daily_log',{p_log_id:dailyLog().id,p_note:null});await loadExecution({force:true,silent:true});await syncDailyReportToCde({silent:true});}render();toast('success',submit?L('تم حفظ وإرسال تقرير اليوم للمراجعة','Daily report saved and submitted for review'):L('تم حفظ سجل اليوم وتحديث نسخة التقرير في الملفات','Daily log saved and report copy updated in Files Workspace'));return true;
  }

  async function handleAction(action,el){
    if(!String(action).startsWith('field-'))return false;
    try{
      if(action==='field-refresh'){local.refreshing=true;await reloadAll();}
      else if(action==='field-open-entity')await navigateToEntity(el.dataset.type,el.dataset.id);
      else if(action==='field-open-cabinet')await navigateToEntity('site_cabinet',el.dataset.id);
      else if(action==='field-open-drawing')await openTakeoff(el.dataset.id,{takeoff:false});
      else if(action==='field-open-takeoff')await openTakeoff(el.dataset.id,{takeoff:true});
      else if(action==='field-open-latest-drawing'){const d=drawings()[0];if(d)await openTakeoff(d.id,{takeoff:false});}
      else if(action==='field-open-latest-takeoff'){const d=drawings()[0];if(d)await openTakeoff(d.id,{takeoff:true});}
      else if(action==='field-new-drawing')await openNewDrawing({projectId:project()?.id,siteId:site()?.id,cabinetId:el.dataset.cabinetId||''});
      else if(action==='field-upload')await openQuickUpload({projectId:project()?.id,siteId:site()?.id,folderId:el.dataset.folderId||null});
      else if(action==='field-open-files')await openQuickUpload({projectId:project()?.id,siteId:site()?.id,folderId:null,openOnly:true});
      else if(action==='field-new-task')openNewTask({project_id:project()?.id,site_id:site()?.id});
      else if(action==='field-daily-log'){if(!dailyLog()&&navigator.onLine){await api.rpc('ensure_site_daily_log',{p_company_id:state.companyId,p_site_id:local.siteId,p_log_date:local.workDate});await loadExecution({force:true,silent:true});}openDailyLog();}
      else if(action==='field-submit-day'){const form=document.querySelector('[data-form="field-daily-log"]');if(form)await saveDailyForm(form,{submit:true});closeOverlay();}
      else if(action==='field-approve-day'){await api.rpc('review_site_daily_log',{p_log_id:dailyLog().id,p_decision:'approved',p_note:null});await loadExecution({force:true,silent:true});await syncDailyReportToCde({silent:true});closeOverlay();toast('success',L('تم اعتماد تقرير اليوم','Daily report approved'));render();}
      else if(action==='field-return-day'){openReasonDialog('field-return-day-submit',L('إرجاع التقرير للمشرف','Return report to supervisor'),L('وضح المطلوب تعديله قبل إعادة الإرسال.','Explain what must change before resubmission.'),dailyLog().id);}
      else if(action==='field-end-day')await openEndOfDay();
      else if(action==='field-weekly')await openWeekly();
      else if(action==='field-new-inspection')openInspectionEditor();
      else if(action==='field-open-inspection')await openInspectionEditor(el.dataset.id);
      else if(action==='field-inspection-result'){const card=el.closest('.field-inspection-item');card?.querySelectorAll('[data-action="field-inspection-result"]').forEach(b=>b.classList.toggle('active',b===el));if(card){card.dataset.result=el.dataset.result;card.classList.remove('pass','fail','na','pending');card.classList.add(el.dataset.result);} }
      else if(action==='field-complete-inspection'){const form=document.querySelector('[data-form="field-inspection-save"]');if(form)await saveInspectionForm(form,true);}
      else if(action==='field-view-inspections'){openDrawer({title:L('الفحوصات الميدانية','Field inspections'),body:`<div class="field-execution-list">${inspections().map(inspectionRow).join('')}</div>`});}
      else if(action==='field-new-issue')openIssueEditor();
      else if(action==='field-open-issue')openIssueEditor(el.dataset.id);
      else if(action==='field-view-issues'){openDrawer({title:L('المشاكل المفتوحة','Open field issues'),body:`<div class="field-execution-list">${issues().map(issueRow).join('')}</div>`});}
      else if(action==='field-issue-status'){await api.rpc('update_site_field_issue',{p_issue_id:el.dataset.id,p_status:el.dataset.status,p_note:null,p_assigned_to:null});await loadExecution({force:true,silent:true});closeOverlay();render();}
      else if(action==='field-issue-close'){openReasonDialog('field-issue-close-submit',L('إغلاق المشكلة','Close field issue'),L('اكتب ماذا تم لحل المشكلة ليبقى السجل مفهومًا.','Record how the issue was resolved so the history remains clear.'),el.dataset.id,false);}
      else if(action==='field-new-constraint')openConstraintEditor();
      else if(action==='field-open-constraint')openConstraintEditor(el.dataset.id);
      else if(action==='field-resolve-constraint'){openReasonDialog('field-resolve-constraint-submit',L('حل العائق','Resolve constraint'),L('سجل كيف تم إزالة سبب التعطيل.','Record how the blocker was removed.'),el.dataset.id,false);}
      return true;
    }catch(err){formError(err,L('تعذر تنفيذ الإجراء','Could not complete the action'));return true;}finally{local.busyAction='';}
  }

  function openReasonDialog(formType,title,subtitle,id,required=true){openDialog({title,subtitle,body:`<form class="form-grid" data-form="${e(formType)}" data-id="${e(id)}"><div class="form-row"><label>${L('الملاحظة','Note')}</label><textarea class="textarea" name="note" rows="4" maxlength="1600" ${required?'required':''} placeholder="${L('اكتب ملاحظة واضحة ومختصرة…','Write a clear, concise note…')}"></textarea><small>${L('ستظهر الملاحظة في سجل الموقع للمراجعة لاحقًا.','This note remains in the site history for later review.')}</small></div><button class="btn btn-primary" type="submit">${icon('check',14)} ${L('تأكيد','Confirm')}</button></form>`});}

  async function saveInspectionForm(form,complete=false){const id=form.dataset.id,current=inspections().find(x=>x.id===id);if(!current)return;const results=arr(current.items).map(it=>{const card=[...document.querySelectorAll('.field-inspection-item')].find(x=>x.querySelector(`[data-key="${CSS.escape(it.item_key)}"]`));const active=card?.querySelector('[data-action="field-inspection-result"].active');return{item_key:it.item_key,result:active?.dataset.result||it.result||'pending',note:card?.querySelector(`[data-inspection-note="${CSS.escape(it.item_key)}"]`)?.value||null,evidence_document_id:card?.querySelector(`[data-inspection-evidence="${CSS.escape(it.item_key)}"]`)?.value||null};});await api.rpc('save_site_inspection',{p_inspection_id:id,p_results:results,p_overall_note:new FormData(form).get('overall_note')||null,p_complete:complete});await loadExecution({force:true,silent:true});closeOverlay();toast('success',complete?L('تم إنهاء الفحص','Inspection completed'):L('تم حفظ الفحص','Inspection saved'));render();}

  async function handleSubmit(form){
    const type=form.dataset.form;if(!String(type||'').startsWith('field-'))return false;
    try{
      setBusy(type);
      if(type==='field-daily-log')await saveDailyForm(form,{submit:false});
      else if(type==='field-inspection-create'){const d=Object.fromEntries(new FormData(form).entries());const r=await api.rpc('create_site_inspection',{p_company_id:state.companyId,p_site_id:local.siteId,p_template_id:d.template_id||null,p_cabinet_id:d.cabinet_id||null,p_drawing_id:null,p_task_id:null,p_title:d.title||null});await loadExecution({force:true,silent:true});closeOverlay();render();await openInspectionEditor(r.inspection?.id);}
      else if(type==='field-inspection-save')await saveInspectionForm(form,false);
      else if(type==='field-issue'){const d=Object.fromEntries(new FormData(form).entries());await api.rpc('create_site_field_issue',{p_company_id:state.companyId,p_site_id:local.siteId,p_payload:{title:d.title,description:d.description||null,severity:d.severity,cabinet_id:d.cabinet_id||null,location_note:d.location_note||null}});await loadExecution({force:true,silent:true});closeOverlay();toast('success',L('تم تسجيل المشكلة','Issue logged'));render();}
      else if(type==='field-constraint'){const d=Object.fromEntries(new FormData(form).entries());await api.rpc('save_site_constraint',{p_company_id:state.companyId,p_site_id:local.siteId,p_constraint_id:null,p_payload:{constraint_type:d.constraint_type,title:d.title,description:d.description||null,impact:d.impact||null}});await loadExecution({force:true,silent:true});closeOverlay();toast('success',L('تم تسجيل العائق','Constraint logged'));render();}
      else if(type==='field-return-day-submit'){const note=String(new FormData(form).get('note')||'').trim();await api.rpc('review_site_daily_log',{p_log_id:form.dataset.id,p_decision:'returned',p_note:note});await loadExecution({force:true,silent:true});closeOverlay();toast('success',L('تم إرجاع التقرير مع الملاحظة','Report returned with the review note'));render();}
      else if(type==='field-issue-close-submit'){const note=String(new FormData(form).get('note')||'').trim();await api.rpc('update_site_field_issue',{p_issue_id:form.dataset.id,p_status:'closed',p_note:note||null,p_assigned_to:null});await loadExecution({force:true,silent:true});closeOverlay();toast('success',L('تم إغلاق المشكلة وتسجيل الحل','Issue closed and resolution recorded'));render();}
      else if(type==='field-resolve-constraint-submit'){const note=String(new FormData(form).get('note')||'').trim();await api.rpc('resolve_site_constraint',{p_constraint_id:form.dataset.id,p_note:note||null});await loadExecution({force:true,silent:true});closeOverlay();toast('success',L('تم حل العائق وتحديث السجل','Constraint resolved and history updated'));render();}
      return true;
    }catch(err){formError(err,L('تعذر حفظ بيانات التنفيذ','Could not save execution data'));return true;}finally{setBusy('');}
  }

  async function openEntity(type,id,siteId,workDate=null){if(siteId&&siteId!==local.siteId){local.siteId=siteId;localStorage.setItem(siteKey,local.siteId);local.loadedKey='';local.execution=null;}if(workDate){local.workDate=String(workDate).slice(0,10);localStorage.setItem(dateKey,local.workDate);}await load({force:true});render();await new Promise(r=>setTimeout(r,0));if(type==='site_daily_log')openDailyLog();else if(type==='site_inspection')await openInspectionEditor(id);else if(type==='site_field_issue')openIssueEditor(id);else if(type==='site_constraint')openConstraintEditor(id);}

  async function handleChange(ev){const target=ev.target;if(target.hasAttribute('data-field-site')){local.siteId=target.value;localStorage.setItem(siteKey,local.siteId);local.loadedKey='';local.execution=null;await load({force:true});return true;}if(target.hasAttribute('data-field-date')){local.workDate=target.value||today();localStorage.setItem(dateKey,local.workDate);local.weekly=null;await loadExecution({force:true});return true;}return false;}
  return {page,load,loadExecution,openEntity,reset,help,handleAction,handleSubmit,handleChange,state:local};
}
